Status Face::dispatch(uint8_t cmd_id, std::span<const uint8_t> args, Reply &)
{
    switch (cmd_id) {
    case kCmdShow: {
        if (!fr::proto::decode_empty(args)) {
            return std::unexpected(Err::invalid_args);
        }
        return show();
    }
    case kCmdInput: {
        const auto a = decode_face_input_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return input(*a);
    }
    case kCmdSet: {
        const auto a = decode_face_set_args(args);
        if (!a || !fr::cap::valid(*a)) {
            return std::unexpected(Err::invalid_args);
        }
        return set(*a);
    }
    default:
        return std::unexpected(Err::unsupported);
    }
}

void Face::report_all()
{
    report_mode(mode());
    report_screen(screen());
    report_focus(focus());
    report_step(step());
    report_utc_offset_min(utc_offset_min());
    report_shown(shown());
    report_time_valid(time_valid());
    report_time_source(time_source());
    report_power_save(power_save());
    report_chime(chime());
    report_clicks(clicks());
}

void Face::encode_traits(fr::wire::Writer &w) const
{
    encode(traits(), w);
}

void Face::report_mode(FaceMode v, TimeUs at)
{
    if (sink_ == nullptr) {
        return;
    }
    uint8_t buf[kFaceModeStateMaxSize];
    fr::wire::Writer w(buf, sizeof(buf));
    encode_face_mode_state(v, w);
    sink_->property(port_, kPropMode, w.bytes(), at);
}

